// Initialize the timer subsystem.
init();

// Track initialization epochs so handles created before a reset are rejected safely.
int gen = FUZZ_GET_ATTR_INT_GLOBAL("init_gen");
FUZZ_SET_ATTR_INT_GLOBAL("init_gen", gen + 1);

// Validation: Sets a monotonically increasing init_gen used by other stubs to enforce pre/post-init semantics.

// allocateTimer requires the subsystem to be initialized.
int gen = FUZZ_GET_ATTR_INT_GLOBAL("init_gen");
if (gen <= 0) { FUZZ_BAIL(); }

// Obtain a free timer ID.
unsigned int id = allocateTimer();

// Wrap the primitive ID in an opaque handle object for the fuzzer pool.
// Use a non-null token pointer as the identity; attributes carry the actual ID.
void *timer_handle = (void *)(unsigned long)(id + 1u);

// Track lifecycle and provenance on the handle.
FUZZ_SET_ATTR_INT(timer_handle, "id", (int)id);
FUZZ_SET_ATTR_INT(timer_handle, "allocated", 1);       // allocated from free stack
FUZZ_SET_ATTR_INT(timer_handle, "linked", 0);          // not in any list yet
FUZZ_SET_ATTR_INT(timer_handle, "component", -1);      // unknown/unset
FUZZ_SET_ATTR_INT(timer_handle, "componentKnown", 0);  // component membership unknown
FUZZ_SET_ATTR_INT(timer_handle, "gen", gen);           // init generation when obtained

// Validation: Ensures init was called and produces a non-null opaque handle with tracked ID and state.

// Validate initialization epoch consistency.
int curGen = FUZZ_GET_ATTR_INT_GLOBAL("init_gen");
int hGen = FUZZ_GET_ATTR_INT(timer_handle, "gen");
if (hGen != curGen || curGen <= 0) { FUZZ_BAIL(); }

// Enforce lifecycle requirements: must be allocated and not linked.
int allocated = FUZZ_GET_ATTR_INT(timer_handle, "allocated");
int linked = FUZZ_GET_ATTR_INT(timer_handle, "linked");
if (!allocated || linked) { FUZZ_BAIL(); }

unsigned int id = (unsigned int)FUZZ_GET_ATTR_INT(timer_handle, "id");

// Return the timer ID to the free stack.
freeTimer(id);

// Mark handle as freed so it won't be reused incorrectly.
FUZZ_SET_ATTR_INT(timer_handle, "allocated", 0);
FUZZ_SET_ATTR_INT(timer_handle, "linked", 0);
FUZZ_SET_ATTR_INT(timer_handle, "component", -1);
FUZZ_SET_ATTR_INT(timer_handle, "componentKnown", 0);

// Validation: Only frees timers that were allocated and not in any list; handle is dropped by not returning it.

// Prepare zero-initialized component array and biggest index per requirements.
unsigned int comps[5] = {0,0,0,0,0};
unsigned int biggest = 0;

// Any ms is allowed; generate fuzzed milliseconds.
unsigned int ms = *FUZZ_PARAM(unsigned int);

// Call the target function.
unsigned int overshoot = divideComponents(comps, &biggest, ms);

// Basic property checks per description: overshoot matches rounding to next 10ms tick.
unsigned int expOvershoot = (ms % 10 == 0) ? 0u : (10u - (ms % 10u));
FUZZ_ASSERT(overshoot == expOvershoot, "overshoot must equal 10 - (ms % 10) when ms not multiple of 10");
if (ms % 10u != 0u) {
    // components[0] should have been incremented due to rounding up.
    FUZZ_ASSERT(comps[0] > 0u, "components[0] should be incremented for non-10ms multiples");
}

