int curGen = FUZZ_GET_ATTR_INT_GLOBAL("init_gen");
int hGen = FUZZ_GET_ATTR_INT(timer_handle, "gen");
if (hGen != curGen || curGen <= 0) { FUZZ_BAIL(); }

